// Resolvers whose small badge is a bitmap rather than a path (no usable
// monochrome vector). Full-colour images sit on the resolver-coloured badge.
const SERVICE_LOGO_IMAGES = {
  soundcloud: { src: 'assets/icons/soundcloud-icon-white.png', alt: 'SoundCloud' },
  subsonic: { src: 'assets/icons/subsonic-icon.png', alt: 'Subsonic' }
};

// Helper to create resolver icon at any size. SERVICE_LOGO_PATHS entries are
// a 24x24 path string, or { d, viewBox } for a path drawn in its own box.
const ResolverIcon = ({ resolverId, size = 14, fill = 'white' }) => {
  const image = SERVICE_LOGO_IMAGES[resolverId];
  if (image) {
    return React.createElement('img', {
      src: image.src,
      width: size,
      height: size,
      alt: image.alt,
      style: { flexShrink: 0, objectFit: 'contain' }
    });
  }
  const entry = SERVICE_LOGO_PATHS[resolverId];
  if (!entry) return null;
  const path = typeof entry === 'string' ? entry : entry.d;
  const viewBox = (typeof entry === 'string' ? null : entry.viewBox) || '0 0 24 24';
  return React.createElement('svg', {
    viewBox,
    width: size,
    height: size,
    fill: fill,
    style: { flexShrink: 0 }
  }, React.createElement('path', { d: path }));
};

